import json, numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
r=Robot()
spec=r.spec()
J=np.array(spec['arm']['position_m']); axes=np.array(spec['arm']['axis']); EE=np.array(spec['arm']['end_effector']['position_m'])
cam=spec['cameras']['robot_wrist']; CP=np.array(cam['pose']['position_m']); CF=np.array(cam['pose']['forward']); CU=np.array(cam['pose']['up']); CR=np.array(cam['pose']['right']); focal=240/np.tan(np.deg2rad(cam['fovy_deg']/2))
obs=r.observe(images=False)
actions=[]
def fk(q,base=None):
    R=np.eye(3);t=np.zeros(3)
    for p,a,v in zip(J,axes,q):
        rot=Rotation.from_rotvec(a*v).as_matrix()
        t=t+R@(p-rot@p);R=R@rot
    if base is not None:
        rb=Rotation.from_euler('z',base[2]).as_matrix();t=rb@t+np.r_[base[:2],0];R=rb@R
    return R,t

def info():
    p=obs['proprio'];R,t=fk(p['arm_pos'],p['base_pose']);print('status', {k:obs[k] for k in ['step','done','reason','blocked'] if k in obs},'proprio',p,'EE',R@EE+t,'camera',R@CP+t,'forward',R@CF,flush=True)

def act(a,images=False):
    global obs
    obs=r.step('delta',np.asarray(a).tolist(),images=images);actions.extend(np.asarray(a).reshape(-1,11)[:obs.get('executed',1)].tolist());json.dump(actions,open('/app/output/actions.json','w'));info();return obs

def look():
    global obs
    obs=r.observe(images=['robot_wrist']);Image.fromarray(obs['images']['robot_wrist']).save('/app/output/view.png');np.save('/app/output/depth.npy',obs['depth']['robot_wrist']);info()

def ik(target,rot=None,q=None):
    p=obs['proprio'];base=p['base_pose'];q=np.array(p['arm_pos'] if q is None else q)
    def err(x):
        R,t=fk(x,base);e=(R@EE+t-np.array(target))*5
        if rot is not None:e=np.r_[e, Rotation.from_matrix(np.asarray(rot)@R.T).as_rotvec()*.8]
        return np.r_[e,(x-q)*.001]
    lo=np.array([-100,-2.41,-100,-2.66,-100,-2.23,-100]);hi=-lo
    res=least_squares(err,q,bounds=(lo,hi),max_nfev=500,ftol=1e-11,gtol=1e-11,xtol=1e-11)
    print('IK err',err(res.x)[:6],flush=True);return res.x

def joints(q):
    cur=np.array(obs['proprio']['arm_pos']);diff=np.array(q)-cur;n=int(np.ceil(np.max(np.abs(diff))/.08));
    if n:act(np.tile(np.r_[0,0,0,diff/n,0],(n,1)))

def move(target,rot=None):joints(ik(target,rot))

def base(dx,dy,yaw=0):
    n=max(1,int(np.ceil(max(np.hypot(dx,dy)/.04,abs(yaw)/.08))));act(np.tile(np.r_[dx/n,dy/n,yaw/n,np.zeros(8)],(n,1)))

def cloud():
    p=obs['proprio'];R,t=fk(p['arm_pos'],p['base_pose']);d=obs['depth']['robot_wrist'];y,x=np.indices(d.shape);v=(x-319.5)[...,None]/focal*CR+(239.5-y)[...,None]/focal*CU+CF;return (v*d[...,None])@R.T+(R@CP+t)

if __name__=='__main__':
    import sys
    if '--replay' in sys.argv:
        for a in json.load(open('/app/output/actions.json')):
            o=r.step('delta',a,images=False)
            if o['done']:print(o['reason']);break
    else:
        print('Ready',flush=True)
        for line in sys.stdin:
            try:exec(line,globals())
            except Exception as e:print(type(e).__name__,str(e),flush=True)
